// Helper functions for the Home module
export function getRandomTip() {
  const idx = Math.floor(Math.random() * LAB_PRO_TIPS.length);
  return LAB_PRO_TIPS[idx];
}

export function getTipOfTheDay() {
  // Deterministic daily tip using calendar day of the year
  const now = new Date();
  const start = new Date(now.getFullYear(), 0, 0);
  const diff = now - start;
  const oneDay = 1000 * 60 * 60 * 24;
  const dayOfYear = Math.floor(diff / oneDay);
  const idx = dayOfYear % LAB_PRO_TIPS.length;
  return LAB_PRO_TIPS[idx];
}